arguments.content:
:root {
  --primary-dark: #171717;
  --accent-blue: #0072F5;
  --bg-light: #FAFAFA;
  --bg-white: #FFFFFF;
  --border-color: #EAEAEA;
  --text-muted: #666666;
  --text-light: #888888;
  --radius: 8px;
  --radius-lg: 12px;
  --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05), 0 2px 4px -1px rgba(0, 0, 0, 0.03);
  --shadow-hover: 0 10px 15px -3px rgba(0, 0, 0, 0.05), 0 4px 6px -2px rgba(0, 0, 0, 0.03);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background-color: var(--bg-light);
  color: var(--primary-dark);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a {
  text-decoration: none;
  color: inherit;
}

ul {
  list-style: none;
}

/* Header */
.site-header {
  background-color: var(--bg-white);
  border-bottom: 1px solid var(--border-color);
  position: sticky;
  top: 0;
  z-index: 100;
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 24px;
  height: 64px;
  max-width: 1200px;
  margin: 0 auto;
}

.logo {
  font-weight: 700;
  font-size: 1.25rem;
  letter-spacing: -0.02em;
}

.nav-links {
  display: flex;
  gap: 24px;
  align-items: center;
}

.nav-links a {
  font-size: 0.875rem;
  color: var(--text-muted);
  font-weight: 500;
  transition: color 0.2s;
}

.nav-links a:hover {
  color: var(--primary-dark);
}

.dropdown {
  position: relative;
}

.dropdown-toggle {
  background: none;
  border: none;
  font-size: 0.875rem;
  color: var(--text-muted);
  font-weight: 500;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 4px;
  font-family: inherit;
  padding: 8px 0;
}

.dropdown-toggle:hover {
  color: var(--primary-dark);
}

.dropdown-menu {
  position: absolute;
  top: 100%;
  left: 0;
  background: var(--bg-white);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 16px;
  opacity: 0;
  visibility: hidden;
  transition: all 0.2s ease;
  transform: translateY(10px);
  min-width: 200px;
}

.mega-menu {
  width: 600px;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.dropdown:hover .dropdown-menu {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.menu-section h4 {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-light);
  margin-bottom: 12px;
}

.menu-section ul {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.menu-section a {
  font-size: 0.875rem;
  color: var(--primary-dark);
  font-weight: 400;
}

.menu-section a:hover {
  color: var(--accent-blue);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 16px;
}

.header-actions a {
  font-size: 0.875rem;
  font-weight: 500;
}

.btn-primary {
  background-color: var(--primary-dark);
  color: var(--bg-white) !important;
  padding: 8px 16px;
  border-radius: 6px;
  transition: background-color 0.2s;
}

.btn-primary:hover {
  background-color: #333;
}

/* Main Content */
main {
  max-width: 1200px;
  margin: 0 auto;
  padding: 48px 24px;
}

.blog-header {
  text-align: center;
  margin-bottom: 48px;
}

.blog-header h1 {
  font-size: 3rem;
  letter-spacing: -0.03em;
  margin-bottom: 16px;
}

.blog-header p {
  font-size: 1.25rem;
  color: var(--text-muted);
}

/* Filters */
.filters-section {
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin-bottom: 48px;
}

@media (min-width: 768px) {
  .filters-section {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
  }
}

.category-pills {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.pill {
  background-color: var(--bg-white);
  border: 1px solid var(--border-color);
  color: var(--text-muted);
  padding: 6px 14px;
  border-radius: 99px;
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s;
  font-family: inherit;
}

.pill:hover {
  border-color: var(--text-muted);
  color: var(--primary-dark);
}

.pill.active {
  background-color: var(--primary-dark);
  color: var(--bg-white);
  border-color: var(--primary-dark);
}

.search-container input {
  padding: 8px 16px;
  border: 1px solid var(--border-color);
  border-radius: 20px;
  font-size: 0.875rem;
  width: 100%;
  max-width: 300px;
  outline: none;
  font-family: inherit;
}

.search-container input:focus {
  border-color: var(--accent-blue);
  box-shadow: 0 0 0 2px rgba(0, 114, 245, 0.2);
}

/* Featured Articles */
.featured-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
  margin-bottom: 64px;
}

@media (min-width: 992px) {
  .featured-grid {
    grid-template-columns: 2fr 1fr;
    grid-template-rows: auto auto;
  }
  .featured-large {
    grid-row: span 2;
  }
}

.article-card {
  background: var(--bg-white);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 24px;
  display: flex;
  flex-direction: column;
  transition: box-shadow 0.2s, transform 0.2s;
  cursor: pointer;
  height: 100%;
}

.article-card:hover {
  box-shadow: var(--shadow-hover);
  transform: translateY(-2px);
}

.card-meta {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 0.875rem;
  color: var(--text-muted);
  margin-bottom: 12px;
}

.category-tag {
  color: var(--accent-blue);
  font-weight: 500;
}

.card-title {
  font-size: 1.5rem;
  letter-spacing: -0.02em;
  margin-bottom: 12px;
  line-height: 1.3;
}

.featured-large .card-title {
  font-size: 2.5rem;
  margin-bottom: 16px;
}

.card-excerpt {
  color: var(--text-muted);
  margin-bottom: 24px;
  flex-grow: 1;
}

.featured-large .card-excerpt {
  font-size: 1.125rem;
}

.stats-box {
  background: var(--bg-light);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 16px;
  margin: 16px 0 24px;
}

.stats-box ul {
  list-style: disc;
  padding-left: 20px;
  color: var(--text-muted);
  font-size: 0.875rem;
}

.stats-box li {
  margin-bottom: 4px;
}

.stats-box strong {
  color: var(--primary-dark);
}

.card-author {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.875rem;
  font-weight: 500;
}

.author-avatar {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background-color: var(--border-color);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.6rem;
  color: var(--text-muted);
}

/* Latest News */
.section-title {
  font-size: 1.5rem;
  letter-spacing: -0.02em;
  margin-bottom: 24px;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--border-color);
}

.latest-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
}

@media (min-width: 768px) {
  .latest-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 992px) {
  .latest-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.no-results {
  text-align: center;
  padding: 48px;
  color: var(--text-muted);
  display: none;
  grid-column: 1 / -1;
  background: var(--bg-white);
  border: 1px dashed var(--border-color);
  border-radius: var(--radius-lg);
}

.load-more-container {
  display: flex;
  justify-content: center;
  margin-top: 48px;
}

.btn-secondary {
  background: var(--bg-white);
  border: 1px solid var(--border-color);
  color: var(--primary-dark);
  padding: 10px 24px;
  border-radius: 6px;
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s;
  font-family: inherit;
}

.btn-secondary:hover {
  border-color: var(--text-muted);
}

/* CTA Banner */
.cta-banner {
  background: var(--primary-dark);
  color: var(--bg-white);
  border-radius: var(--radius-lg);
  padding: 64px 24px;
  text-align: center;
  margin: 64px auto 0;
  max-width: 1200px;
}

.cta-banner h2 {
  font-size: 2.5rem;
  letter-spacing: -0.03em;
  margin-bottom: 16px;
}

.cta-banner p {
  color: var(--text-light);
  font-size: 1.125rem;
  margin-bottom: 32px;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.cta-actions {
  display: flex;
  justify-content: center;
  gap: 16px;
  margin-bottom: 32px;
}

.btn-light {
  background: var(--bg-white);
  color: var(--primary-dark);
  padding: 12px 24px;
  border-radius: 6px;
  font-weight: 500;
  transition: background 0.2s;
}

.btn-light:hover {
  background: #f0f0f0;
}

.btn-outline {
  background: transparent;
  color: var(--bg-white);
  border: 1px solid rgba(255, 255, 255, 0.2);
  padding: 12px 24px;
  border-radius: 6px;
  font-weight: 500;
  transition: border-color 0.2s;
}

.btn-outline:hover {
  border-color: rgba(255, 255, 255, 0.5);
}

.enterprise-block {
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  padding-top: 32px;
  color: var(--text-light);
}

.enterprise-block a {
  color: var(--bg-white);
  text-decoration: underline;
  text-decoration-color: rgba(255, 255, 255, 0.3);
  text-underline-offset: 4px;
}

.enterprise-block a:hover {
  text-decoration-color: var(--bg-white);
}

/* Footer */
.site-footer {
  background: var(--bg-white);
  border-top: 1px solid var(--border-color);
  padding: 64px 24px 32px;
  margin-top: 64px;
}

.footer-inner {
  max-width: 1200px;
  margin: 0 auto;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 32px;
  margin-bottom: 64px;
}

@media (min-width: 768px) {
  .footer-grid {
    grid-template-columns: repeat(4, 1fr);
  }
}

@media (min-width: 1024px) {
  .footer-grid {
    grid-template-columns: repeat(6, 1fr);
  }
}

.footer-section h5 {
  font-size: 0.875rem;
  color: var(--primary-dark);
  margin-bottom: 16px;
}

.footer-section ul {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.footer-section a {
  font-size: 0.875rem;
  color: var(--text-muted);
}

.footer-section a:hover {
  color: var(--primary-dark);
}

.footer-bottom {
  display: flex;
  flex-direction: column;
  gap: 16px;
  border-top: 1px solid var(--border-color);
  padding-top: 32px;
}

@media (min-width: 768px) {
  .footer-bottom {
    flex-direction: row;
    justify-content: space-between;
    align-items: center;
  }
}

.status {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.875rem;
  color: var(--text-muted);
}

.status-indicator {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background-color: #0070F3;
}

.logo-small {
  font-weight: 700;
  color: var(--primary-dark);
}

document.addEventListener('DOMContentLoaded', () => {
  const pills = document.querySelectorAll('.pill');
  const articles = document.querySelectorAll('.latest-grid .article-card');
  const searchInput = document.getElementById('search-input');
  const noResults = document.getElementById('no-results');
  const loadMoreBtn = document.getElementById('load-more-btn');

  let currentCategory = 'All Posts';
  let searchQuery = '';

  // Initialize to show only 6 initially in the grid (but some are hidden by JS)
  // We'll manage visible items with a max count
  let visibleCount = 6;

  function updateGrid() {
    let visibleTotal = 0;
    let matchCount = 0;

    articles.forEach((article, index) => {
      const category = article.getAttribute('data-category');
      const title = article.getAttribute('data-title').toLowerCase();
      const content = article.innerText.toLowerCase();

      const matchesCategory = currentCategory === 'All Posts' || category === currentCategory;
      const matchesSearch = searchQuery === '' || title.includes(searchQuery) || content.includes(searchQuery);

      if (matchesCategory && matchesSearch) {
        matchCount++;
        if (matchCount <= visibleCount) {
          article.style.display = 'flex';
          visibleTotal++;
        } else {
          article.style.display = 'none';
        }
      } else {
        article.style.display = 'none';
      }
    });

    if (matchCount === 0) {
      noResults.style.display = 'block';
    } else {
      noResults.style.display = 'none';
    }

    if (matchCount > visibleCount) {
      loadMoreBtn.style.display = 'inline-block';
    } else {
      loadMoreBtn.style.display = 'none';
    }
  }

  // Category Filtering
  pills.forEach(pill => {
    pill.addEventListener('click', () => {
      pills.forEach(p => p.classList.remove('active'));
      pill.classList.add('active');
      currentCategory = pill.getAttribute('data-category');
      visibleCount = 6; // Reset visible count on filter change
      updateGrid();
    });
  });

  // Search Filtering
  searchInput.addEventListener('input', (e) => {
    searchQuery = e.target.value.toLowerCase();
    visibleCount = 6; // Reset visible count on search change
    updateGrid();
  });

  // Load More
  if (loadMoreBtn) {
    loadMoreBtn.addEventListener('click', () => {
      visibleCount += 6; // Show 6 more
      updateGrid();
    });
  }

  // Initial render
  updateGrid();
});
